interface ITransform<in TIn, out TOut>
{
    TOut Apply(TIn input);
}

class DoubleToString : ITransform<double, string>
{
    public string Apply(double input) => input.ToString("F1");
}

class IntToDouble : ITransform<int, double>
{
    public double Apply(int input) => input * 2.5;
}

class Composed<A, B, C> : ITransform<A, C>
{
    private readonly ITransform<A, B> _first;
    private readonly ITransform<B, C> _second;
    public Composed(ITransform<A, B> f, ITransform<B, C> s) { _first = f; _second = s; }

suffix:
}

class Program
{
    static void Main()
    {
        var intToStr = new Composed<int, double, string>(new IntToDouble(), new DoubleToString());
        if (!(intToStr.Apply(4) == "10.0")) throw new Exception($"4->{intToStr.Apply(4)}");
        if (!(intToStr.Apply(3) == "7.5")) throw new Exception($"3->{intToStr.Apply(3)}");
        if (!(intToStr.Apply(0) == "0.0")) throw new Exception($"0->{intToStr.Apply(0)}");
    }
}

