using System;

class Program
{
    static string Describe(int[] arr) => arr switch
    {
        [] => "empty",
        [var x] => $"single:{x}",
        [var f, .., var l] when f == l => $"bookend:{f}",

suffix:
        _ => "other"
    };

    static void Main()
    {
        if (!(Describe(Array.Empty<int>()) == "empty")) throw new Exception("t1");
        if (!(Describe(new[] { 42 }) == "single:42")) throw new Exception("t2");
        if (!(Describe(new[] { 5, 9, 5 }) == "bookend:5")) throw new Exception("t3");
        if (!(Describe(new[] { 1, 2 }) == "pair:1,2")) throw new Exception("t4");
        if (!(Describe(new[] { 1, 2, 3, 4 }) == "other")) throw new Exception("t5");
    }
}
